// Edit this list - one city per line, "Roofing City, ST" format works well as a search term
const cities = [
  'Roofing companies in Columbus, OH',
  'Roofing companies in Tulsa, OK',
  'Roofing companies in Greenville, SC'
];

return cities.map(c => ({ json: { searchTerm: c } }));

// Apify's response can arrive two different ways depending on n8n's HTTP Request
// settings: either as ONE item containing the whole array, or auto-split into
// MANY items (one per business). Handle both so this never silently returns nothing.

let places;

if (items.length > 1) {
  // n8n already split the array into one item per place
  places = items.map(i => i.json);
} else {
  const first = items[0] ? items[0].json : null;
  if (Array.isArray(first)) {
    places = first;
  } else if (first && Array.isArray(first.items)) {
    places = first.items;
  } else if (first) {
    places = [first];
  } else {
    places = [];
  }
}

const noWebsite = places.filter(p => !p.website || p.website.trim() === '');

return noWebsite.map(p => ({
  json: {
    'Business Name': p.title || '',
    'Phone': p.phone || p.phoneUnformatted || '',
    'City': p.city || p.address || '',
    'State': p.state || (p.address ? (p.address.match(/,\s*([A-Z]{2})\s*\d{5}/) || [])[1] || '' : ''),
    'Rating': p.totalScore || '',
    'Review Count': p.reviewsCount || 0,
    'Website': 'N',
    'Call Status': '',
    'Last Called At': '',
    'Follow Up Date': '',
    'Outcome Summary': '',
    'Transcript': '',
    'Meeting Booked': false,
    'Attempt Count': 0
  }
}));

// De-dupe against what's already in the Sheet, matching on Business Name + Phone
const newLeads = $('Drop Rows Without Phone').all().map(i => i.json);
const existing = $input.all().map(i => i.json);

const existingKeys = new Set(existing.map(e => (e['Business Name'] || '') + '|' + (e['Phone'] || '')));

const deduped = newLeads.filter(l => !existingKeys.has(l['Business Name'] + '|' + l['Phone']));

return deduped.map(l => ({ json: l }));
